(async()=>{'use strict';if(new URLSearchParams(location.search).get('profile')!=='dungeon-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(100);const q=EmberQA,D=SurvivalData,U=SurvivalDungeons,W=EmberTerrain;const output=document.createElement('section');output.style='position:fixed;inset:0;z-index:10000;background:#162021;color:white;overflow:auto;padding:20px';document.body.append(output);const report=document.createElement('pre');report.id='report';output.append(report);const result={},check=(v,s)=>{if(!v)throw Error(s);};document.getElementById('welcome').hidden=true;q.close(false);q.setPlaying(false);const fresh=D.fresh();
q.apply(fresh);q.inventory();result.initialEnabled=[...document.querySelectorAll('[data-action^="deposit:"]:not(:disabled)')].length;result.initialKnown=D.recipes.filter(r=>D.knows(q.state,r.id)).map(r=>r.id);check(result.initialKnown.length===3,'initial lock');q.close(false);
const locked={...fresh,inventory:{wood:40,ore:50,crystal:20,hide:8}};q.apply(locked);q.deposit('jetpack');check(q.state.piles.length===0,'deposit bypass');q.state.piles.push({id:'p1',x:0,z:24,y:q.state.y,items:{ore:12,crystal:6,hide:4}});q.craft('p1','jetpack');check(q.state.jobs.length===0,'craft bypass');
const route=await(await fetch('dungeon-route.json')).json();result.routes=[];
for(const d of U.dungeons){q.apply({...D.fresh(),...d.door});check(q.nearestTarget()?.type==='dungeonEnter','cave door');q.interact();check(U.at(q.state.x,q.state.z,q.state.y)===d,'enter');q.state.x=d.x+.5;q.state.z=d.z+3.5;for(const [x,z]of route.slice(1)){const tx=d.x+x+.5,tz=d.z+z+.5;q.state.yaw=Math.atan2(q.state.x-tx,q.state.z-tz);q.keys({KeyW:true});for(let n=0;n<9;n++)q.move(1/63);q.keys({});check(Math.hypot(q.state.x-tx,q.state.z-tz)<.12,'route blocked '+d.id+' '+x+','+z);}check(q.nearestTarget()?.type==='dungeonTreasure','treasure target');q.interact();check(q.state.openedDungeonChests.includes(d.id),'loot');check(q.state.blueprints.length===D.blueprintSets[d.index].length,'blueprints');q.close(false);result.routes.push({id:d.id,endZ:q.state.z-d.z,blueprints:q.state.blueprints.length});const snap=q.snapshot();q.apply(snap);check(q.nearestTarget()?.type!=='dungeonTreasure','duplicate chest');q.state.x=d.x;q.state.z=d.z+3;q.interact();check(!U.at(q.state.x,q.state.z,q.state.y),'return');}
const d=U.dungeons[0];q.apply({...D.fresh(),x:d.x,z:d.z+30,y:d.y,time:0});q.setPlaying(true);q.step(2.1);check(q.state.hp===82,'spikes damage '+q.state.hp);result.spikeHp=q.state.hp;q.apply({...D.fresh(),x:d.x,z:d.z+13,y:d.y-3,time:0});q.step(2.1);check(q.state.z===d.z+9,'pit recovery');result.pitHp=q.state.hp;q.apply({...D.fresh(),hp:1,inventory:{wood:9},blueprints:['bow'],x:d.x,z:d.z+13,y:d.y-3,time:0});q.step(2.1);check(!U.at(q.state.x,q.state.z,q.state.y),'death respawn');check(q.state.blueprints.includes('bow'),'knowledge lost on death');check(q.state.bags[0].y===d.y&&q.state.bags[0].z===d.z+9,'pit death bag inaccessible');result.deathBagRecoverable=true;q.setPlaying(false);
const saved=D.fresh();for(let i=0;i<3;i++)D.dungeonLoot(saved,i);saved.checkpoint={id:'testcamp',x:0,z:24,y:saved.y};q.apply(saved);check(q.saveSlot(19),'save');q.apply(D.fresh());q.loadSlot(19);check(q.state.blueprints.length===16&&q.state.openedDungeonChests.length===3,'reload');q.close(false);q.setPlaying(false);result.saveKnown=q.state.blueprints.length;result.chests=q.state.openedDungeonChests.length;result.enemies=q.entities.length;
async function shot(id,x,z,yaw,pitch=0){q.apply({...saved,x:d.x+x,z:d.z+z,y:d.y,yaw,pitch,openedDungeonChests:[]});q.close(false);q.setPlaying(false);q.world.update(q.state.time,q.state);q.sky.update(q.state,0,true);await wait(500);q.renderer.render(q.scene,q.camera);const im=document.createElement('img');im.id=id;im.alt=id;im.src=q.renderer.domElement.toDataURL('image/png');im.style='width:49%';output.append(im);}
await shot('pit',0,8.5,Math.PI,-.15);await shot('spikes',0,26.5,Math.PI,-.08);await shot('maze',0,51.5,Math.PI,0);await shot('treasure',0,72,Math.PI,0);report.textContent=JSON.stringify(result,null,2);document.title='ダンジョン確認完了';})().catch(e=>{const p=document.getElementById('report')||document.body.appendChild(document.createElement('pre'));p.id='report';p.textContent=e.stack;});
